package com.ecommerce.commerceapi.products.domain;
import com.ecommerce.commerceapi.masters.domain.Color; import com.ecommerce.commerceapi.masters.domain.Size; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="product_variants") public class ProductVariant { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id",nullable=false) private Product product; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="color_id",nullable=false) private Color color; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="size_id",nullable=false) private Size size; @Column(nullable=false,unique=true) private String sku; @Column(nullable=false) private BigDecimal costPrice,sellingPrice,mrp; @Column(nullable=false) private int reorderLevel; @Column(nullable=false) private boolean active=true; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @PrePersist void create(){createdAt=updatedAt=Instant.now();} @PreUpdate void update(){updatedAt=Instant.now();}
 public void setProduct(Product v){product=v;} public void setColor(Color v){color=v;} public void setSize(Size v){size=v;} public void setSku(String v){sku=v;} public void setCostPrice(BigDecimal v){costPrice=v;} public void setSellingPrice(BigDecimal v){sellingPrice=v;} public void setMrp(BigDecimal v){mrp=v;} public void setReorderLevel(int v){reorderLevel=v;} public Long getId(){return id;} public Product getProduct(){return product;} public Color getColor(){return color;} public Size getSize(){return size;} public String getSku(){return sku;} public BigDecimal getCostPrice(){return costPrice;} public BigDecimal getSellingPrice(){return sellingPrice;} public BigDecimal getMrp(){return mrp;} public int getReorderLevel(){return reorderLevel;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;}
}
